/* @autogenerated */
package net.civeira.phylax.feature.oauth.mfa.application;

import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.List;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.crypto.PasswordHasher;
import net.civeira.phylax.feature.access.usermfarecoverycode.domain.UserMfaRecoveryCode;
import net.civeira.phylax.feature.access.usermfarecoverycode.domain.UserMfaRecoveryCodeChangeSet;
import net.civeira.phylax.feature.access.usermfarecoverycode.domain.gateway.UserMfaRecoveryCodeCommandRepositoryGateway;
import net.civeira.phylax.feature.access.usermfarecoverycode.domain.gateway.UserMfaRecoveryCodeFilter;
import net.civeira.phylax.feature.access.usermfarecoverycode.domain.gateway.UserMfaRecoveryCodeQueryRepositoryGateway;
import net.civeira.phylax.feature.identity.user.domain.UserReference;
import net.civeira.phylax.feature.oauth.mfa.domain.gateway.RecoveryCodeConsumptionGateway;

@ApplicationScoped
@RequiredArgsConstructor
public class MfaRecoveryService {

  private static final String ALPHABET = "BCDFGHJKLMNPQRSTVWXZ";
  private static final SecureRandom RANDOM = new SecureRandom();

  private final UserMfaRecoveryCodeQueryRepositoryGateway readGateway;
  private final UserMfaRecoveryCodeCommandRepositoryGateway writeGateway;
  private final PasswordHasher passwordHasher;
  private final RecoveryCodeConsumptionGateway consumption;

  /** Generates {@code count} single-use codes, replacing any existing ones for the user. */
  public List<String> generateCodes(String userUid, int count) {
    writeGateway
        .listForUpdate(UserMfaRecoveryCodeFilter.builder().user(UserReference.of(userUid)).build())
        .forEach(code -> writeGateway.delete(code.delete()));

    List<String> rawCodes = new ArrayList<>(count);
    for (int i = 0; i < count; i++) {
      String raw = generateRawCode();
      UserMfaRecoveryCode entity = UserMfaRecoveryCode.create(new UserMfaRecoveryCodeChangeSet()
          .newUid().user(UserReference.of(userUid)).codeHashPlain(raw));
      writeGateway.create(entity);
      rawCodes.add(raw);
    }
    return rawCodes;
  }

  /** Returns true and marks the code used if it matches an unused code; false otherwise. */
  public boolean consumeCode(String userUid, String rawCode) {
    String candidate = rawCode.trim();
    return readGateway
        .list(UserMfaRecoveryCodeFilter.builder().userUnused(UserReference.of(userUid)).build())
        .stream().filter(c -> c.getCodeHashValue().verify(passwordHasher, candidate)).findFirst()
        // The read only finds the candidate; the conditional update decides who consumes it.
        .map(code -> consumption.consume(code.getUid(), userUid)).orElse(false);
  }

  /** Returns the number of unused recovery codes for the user. */
  public long countUnused(String userUid) {
    return readGateway
        .count(UserMfaRecoveryCodeFilter.builder().userUnused(UserReference.of(userUid)).build());
  }

  private String generateRawCode() {
    char[] buf = new char[8];
    for (int i = 0; i < 8; i++) {
      buf[i] = ALPHABET.charAt(RANDOM.nextInt(ALPHABET.length()));
    }
    return new String(buf, 0, 4) + "-" + new String(buf, 4, 4);
  }

}
